window.__saqPaperQuestions("2018-2-northern-sydney",[{"number":1,"title":"","stemText":"(16 marks) At 8pm a 3 year old boy is brought to your ED. He has known anaphylaxis to strawberry and has drunk strawberry cordial 30 minutes ago. He has swollen eyes and face and has vomited continuously since\narrival. Heart rate is 140 bpm.","parts":[{"id":"a","label":"Part A","prompt":"List your immediate actions (5 marks)"},{"id":"b","label":"Part B","prompt":"The patient requires 2 doses of adrenaline and is subsequently asymptomatic within 30 minutes of arrival. Outline the next steps in the child’s management and disposition. (5 marks)"},{"id":"c","label":"Part C","prompt":"You decide to develop a guideline for adrenaline use in anaphylaxis. List 6 points in developing such a guideline. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Move to resus- Gastric anaphylaxis, requiring adrenaline</div><div class=\"answer-line\">IM adrenaline –</div><div class=\"answer-line\">IM 10 micrograms/kg (0.01 mL/kg adrenaline 1:1000) up to 500 micrograms (0.5 mL). Repeat</div><div class=\"answer-line\">every 3–5 minutes if required.</div><div class=\"answer-line\">Attach monitoring – obtain blood pressure</div><div class=\"answer-line\">Further adrenaline at 3-5 minutes if no improvement</div><div class=\"answer-line\">Obtain IVC access if not improving</div><div class=\"answer-line\">Consider fluid bolus 10ml/kg if hypotensive</div><div class=\"answer-line\">Consider steroids- options – oral prednisone when stop vomiting vs IV hydrocortisone</div><div class=\"answer-line\">Consider adrenaline infusion if no response and remains hypotensive</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">The patient requires 2 doses of adrenaline and is subsequently asymptomatic within 30 minutes</div><div class=\"answer-line\">of arrival. Outline the next steps in the child’s management and disposition. (5 marks)</div><div class=\"answer-line\">Observed for minimum 4 hrs post adrenaline for symptoms</div><div class=\"answer-line\">Admit paediatrics/paed SSU due to late time and transfer to ward when minimum time frame up.</div><div class=\"answer-line\">(shouldn’t go home due to issues around anaphylaxis and night discharge)</div><div class=\"answer-line\">If further adrenaline / infusion / persistent hypotension / severe symptoms required will need</div><div class=\"answer-line\">transfer to tertiary paediatric centre.</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div><div class=\"answer-line\">Explore parental understanding of anaphylaxis and previous education - were they carrying an</div><div class=\"answer-line\">epipen (patient had known anaphylaxis)</div><div class=\"answer-line\">Further education about symptoms of anaphylaxis and allergy - use online resources</div><div class=\"answer-line\">Pharmacy review if able, epipen on discharge plus advice to get further script.</div><div class=\"answer-line\">Parental agreement and understanding of treatment plan, when to call 000</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">You decide to develop a guideline for adrenaline use in anaphylaxis. List 6 points in developing</div><div class=\"answer-line\">such a guideline. (6 marks)</div><div class=\"answer-line\">Research current local emergency guidelines or available within health area</div><div class=\"answer-line\">Research gold standard treatment for diagnosis and treatment of Anaphylaxis– ASCIA, NSW Health,</div><div class=\"answer-line\">Australian prescriber, ETG etc</div><div class=\"answer-line\">Discuss with local stakeholders</div><div class=\"answer-line\">Emergency- medical and nursing</div><div class=\"answer-line\">Paediatrics</div><div class=\"answer-line\">Pharmacy- will need to provide ED epipens for discharge</div><div class=\"answer-line\">Intensive care- include tertiary centres</div><div class=\"answer-line\">Allergy Clinics/ immunologists- for outpatient referrals</div><div class=\"answer-line\">Write a draft guideline</div><div class=\"answer-line\">Send out for comment to invested stakeholders and request comments</div><div class=\"answer-line\">Amend document, send to Director of ED/ Admin for sign off</div><div class=\"answer-line\">Educate staff re document- Simulation sessions, nursing inservices, medical education- all levels –</div><div class=\"answer-line\">need a project lead</div><div class=\"answer-line\">Implement</div><div class=\"answer-line\">Reaudit at 6 months to see improvement/ need for further change</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"(18 marks) A 78 year old female presents with a 24 hour history of exercise induced self-limiting chest pain, intermittent palpitations and a single episode of pre-syncope. She has no significant medical history and takes no medications. She is currently pain free.\n\nVital signs\n\nTemp 37 deg C\nP 160 bpm\n\nBP 168/100 mmHg\n\nRR 20 /min\n\nSaO2 95% on RA","parts":[{"id":"a","label":"Part A","prompt":"List 4 relevant findings on the ECG (4 marks)\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 3"},{"id":"b","label":"Part B","prompt":"List 4 initial treatment options with a brief rationale (4 marks)\nThe patient complains of feeling faint and looks pale and diaphoretic.\n\nVital signs\nP 180 bpm\n\nBP 100/70 mmHg\n\nRR 30 bpm\n\nSaO2 95% on RA"},{"id":"c","label":"Part C","prompt":"Name the rhythm on the monitoring strip (1 mark) and list 3 possible treatment steps (3 marks) A RHYTHM STRIP IS SHOWN IN THE PROPS BOOKLET, PAGE 4"},{"id":"d","label":"Part D","prompt":"After treatment, the patient’s haemodynamics improve and a repeat ECG is performed.\nList 3 relevant findings on the ECG (3 marks)\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 5"},{"id":"e","label":"Part E","prompt":"List 3 possible causes (3 marks)"}],"propPages":["asset:imga5b21e1a8d822771fb","asset:imgb801d4960544cc8208","asset:img2905156c328a885c93"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">AF with RVR</div><div class=\"answer-line\">LBBB (potentially incomplete/borderline)</div><div class=\"answer-line\">TWI I, aVL, V4-V6 (consistent with LBBB)</div><div class=\"answer-line\">Multiple VEBs</div><div class=\"answer-line\">No overt evidence of STEMI</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Dual anti-platelet therapy (possible nstemi/LBBB STEMI)</div><div class=\"answer-line\">Heparin (nstemi/LBBB STEMI; could be PE)</div><div class=\"answer-line\">Continuous cardiac monitoring/defibrillator/cardioversion pads (at risk of deterioration)</div><div class=\"answer-line\">02 to maintain saturations &gt;92-94% (elevated RR, BP suspicious for APO)</div><div class=\"answer-line\">Initial rhythm control strategy</div><div class=\"answer-line\">Amiodarone 300mg q30mins via large bore cannula</div><div class=\"answer-line\">Consider DC cardioversion if becomes more unstable (CP, APO, SBP&lt;100)</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Polymorphic VT</div><div class=\"answer-line\">Cardioversion 150/150/200J as unstable</div><div class=\"answer-line\">Consider giving MgS04 20mmol (1-2g iv q2-10mins) as likely recurrence</div><div class=\"answer-line\">Continue amiodarone loading 900mg/20 hours (likely ischaemic pVT)</div><div class=\"answer-line\">Versus stop if felt this could be causative but likely having runs prior</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">After treatment, the patient’s haemodynamics improve and a repeat ECG is performed.</div><div class=\"answer-line\">List 3 relevant findings on the ECG (3 marks)</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Check for hypoK+, hypoMg+, hypoCa2+</div><div class=\"answer-line\">Consider angiography (myocardial ischaemia)</div><div class=\"answer-line\">SAH/raised ICP (CTB if headache or abnormal LOC)</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"(15 marks)\nA 37 year old man presents with chest pain following cocaine use.","parts":[{"id":"a","label":"Part A","prompt":"List and explain three ways in which cocaine use may cause chest pain (6 marks) During the assessment the patient has a brief self-limited seizure.\n\nVital signs RR 12 bpm\nP 130 bpm\n\nBP 140/69 mmHg\n\nSaO2 95% on RA\n\nTemp 37 deg C"},{"id":"b","label":"Part B","prompt":"An ECG is performed. Describe and interpret the ECG (2 marks)\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 6"},{"id":"c","label":"Part C","prompt":"Describe two pharmacodynamics properties of cocaine that lead to tachydysrhythmias (2 marks)"},{"id":"d","label":"Part D","prompt":"Outline your approach to the treatment of this tachydysrhythmia (3 marks)"},{"id":"e","label":"Part E","prompt":"Beta-selective adrenoreceptor blockers have traditionally been contraindicated in this setting. Why? (2 marks)"}],"propPages":["asset:imgda55debaa367cd6a5a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Sympathomimetc → hypertension &amp; tachycardia → increased myocardial oxygen demand</div><div class=\"answer-line\">+/- Coronary artery vasospasm</div><div class=\"answer-line\">+/- Prothrombotic – increased platelet aggregation → increase risk of cor a occlusion</div><div class=\"answer-line\">+/- Chronic use – systemic inflammatory state &amp; vessel injury → premature atherosclerosis</div><div class=\"answer-line\"><strong>Aortic, coronary (or other vessel) dissection</strong> causing pain. Again chronic inflammatory state →</div><div class=\"answer-line\">vessel injury, weakening of media predisposing to dissection</div><div class=\"answer-line\"><strong>“Crack lung”</strong> (inflammation-mediated acute pulmonary injury) causing hypoxia, pain, infiltrate</div><div class=\"answer-line\"><strong>Myocarditis</strong> – direct inflammatory effect</div><div class=\"answer-line\"><strong>Infective Endocarditis </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">During the assessment the patient has a brief self-limited seizure.</div><div class=\"answer-line\">Vital signs RR 12 bpm</div><div class=\"answer-line\">P 130 bpm</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Sympathomimetic causing increased heart rate</div><div class=\"answer-line\">Class I anti-arrhythmic → Na channel blockade, widening of QRS and QT prolongation</div><div class=\"answer-line\">May induce myocardial ischaemia (see answers above) leading to dysrhythmias</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Seek &amp; treat electrolyte abnormalities</div><div class=\"answer-line\">Sodium bicarb – counters Na blockade</div><div class=\"answer-line\">Benzodiazepines – reduced sympathetic tone</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Beta-selective adrenoreceptor blockers have traditionally been contraindicated in this setting.</div><div class=\"answer-line\">Why? (2 marks)</div><div class=\"answer-line\">Concerns about unopposed alpha activity causing accelerated hypertension. Controversial</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"(17 marks) A 12 year old boy walks into emergency with his father having been knocked out attempting to make a tackle while playing rugby 1 hour ago. He was unconscious for approximately 90 seconds at the time. He now has a moderate headache and has vomited once. GCS is 15 and observations are normal.","parts":[{"id":"a","label":"Part A","prompt":"Outline 5 features of the history and examination that are common across paediatric clinical decision rules that suggest a CT brain is indicated (5 marks)"},{"id":"b","label":"Part B","prompt":"The patient’s father asks about the risk of a CT brain. Outline your response (3 marks)"},{"id":"c","label":"Part C","prompt":"You decide there is no indication for CT - outline your further management (4 marks)"},{"id":"d","label":"Part D","prompt":"On discharge your final diagnosis is concussion. What management plan/advice do you give the child and his parents (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Outline 5 features of the history and examination that are common across paediatric clinical</div><div class=\"answer-line\">decision rules that suggest a CT brain is indicated (5 marks)</div><div class=\"answer-line\">The following are common across PECARN, Chalice &amp; Catch rules with only minor variation in detail</div><div class=\"answer-line\">Dangerous mechanism of action (various descriptors – fall &gt; 1.5m, pedestrian/cyclist vs car, high risk</div><div class=\"answer-line\">MVA)</div><div class=\"answer-line\">Abnormal GCS (various cut-offs)</div><div class=\"answer-line\">Abnormal mental state – variably described as drowsiness, irritability, altered MS)</div><div class=\"answer-line\">Clinical suspicion of skull #, depressed or open skull #</div><div class=\"answer-line\">Clinical suspicion of base of skull # (raccoon eyes, haemotympanum etc)</div><div class=\"answer-line\">Large haematoma – variably further defined by size/location</div><div class=\"answer-line\">Other components of these CDRs that are not common to all (score half mark)</div><div class=\"answer-line\">Severe or worsening headache</div><div class=\"answer-line\">Vomiting – variably defined</div><div class=\"answer-line\">LOC &gt; 5 minutes</div><div class=\"answer-line\">Amnesia &gt; 5 min</div><div class=\"answer-line\">Suspicion of NAI</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div><div class=\"answer-line\">Risk benefit discussion as guided by decision rule</div><div class=\"answer-line\">Concept of radiologically and neurosurgically significant findings</div><div class=\"answer-line\">Expected dose 1mSv is equiv 200 CXR or 1 yr background radiation</div><div class=\"answer-line\">Approx risk malig 1:1500 added to baseline incidence</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">4 hr observation with PTA</div><div class=\"answer-line\">Simple analgesia</div><div class=\"answer-line\">Antiemetic somewhat controversial (??masks vomiting)</div><div class=\"answer-line\">DC plan with warning signs/HI info sheet</div><div class=\"answer-line\">Care of responsible adult</div><div class=\"answer-line\">LMO follow up within 48hr</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">On discharge your final diagnosis is concussion. What management plan/advice do you give the</div><div class=\"answer-line\">child and his parents (5 marks)</div><div class=\"answer-line\">Outline expected symptoms, residual headache/dizziness/concentration issues, consider making</div><div class=\"answer-line\">school aware</div><div class=\"answer-line\">90% recovery by 1/12</div><div class=\"answer-line\">Rest for 1-2 /7, minimise computer screens/phones during this time</div><div class=\"answer-line\">Simple analgesia</div><div class=\"answer-line\">Miss 2 weeks of contact sport then</div><div class=\"answer-line\">Graduated return to play after 14 days aim to return to play end of week 3</div><div class=\"answer-line\">Increasing evidence that light exercise early speeds recovery</div><div class=\"answer-line\">Get clearance from Dr trained in concussion prior to return to play</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"(17 marks) An 80 year old man presents with neck pain after a fall. He has mixed motor and sensory abnormalities and you suspect an incomplete spinal cord injury.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table below with typical features of partial spinal cord syndromes (9 marks) Syndrome Usual mechanism Motor features Sensory features Central cord syndrome Anterior cord syndrome Brown Sequard"},{"id":"b","label":"Part B","prompt":"Explain the typical examination findings in central cord syndrome based on the neuroanatomy of the spinal cord. You may use a diagram. (3 marks)"},{"id":"c","label":"Part C","prompt":"List 5 potential adverse effects or complications of the use of semi-rigid collars for c-spine immobilization (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(17 marks)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Explain the typical examination findings in central cord syndrome based on the neuroanatomy of</div><div class=\"answer-line\">the spinal cord. You may use a diagram. (3 marks)</div><div class=\"answer-line\">The injury occurs as a result of anterior and posterior compression of the spinal cord, leading</div><div class=\"answer-line\">to edema, hemorrhage or ischemia to the central portion of the spinal cord. The site of most injuries</div><div class=\"answer-line\">is in the mid-to-lower cervical cord.</div><div class=\"answer-line\">Due to the anatomical lamination of the corticospinal tract with the arm fibers medially and the leg</div><div class=\"answer-line\">fibers laterally, the arms are affected more so than the legs, resulting in a disproportionate motor</div><div class=\"answer-line\">impairment (see the illustration below).</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List 5 potential adverse effects or complications of the use of semi-rigid collars for c-spine</div><div class=\"answer-line\">immobilization (5 marks)</div><div class=\"answer-line\">Pressure on neck veins leading to increased intracranial pressure</div><div class=\"answer-line\">Pressure injuries around occiput/elsewhere</div><div class=\"answer-line\">Pain/discomfort</div><div class=\"answer-line\">Unnecessary movement of head/neck while sizing &amp; fitting collar</div><div class=\"answer-line\">Limited mouth opening and difficulty swallowing</div><div class=\"answer-line\">Airway compromise if vomiting</div><div class=\"answer-line\">Intubation difficulties</div><div class=\"answer-line\">Conceals potentially serious injuries (esp in penetrating neck trauma)</div><div class=\"answer-line\">Causes some hyperextension</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"(16 marks) A 40 year old female has been brought in following increasing confusion and agitation at home this morning. She is day 3 after normal vaginal delivery of a healthy baby at another hospital, but her antenatal history is unknown. Ambulance officers report a generalised tonic-clonic seizure which\nstopped with 5mg IV midazolam to terminate.\n\nVital signs\nP 130 bpm\n\nBP 180/100 mmHg\n\nRR 40 bpm\n\nSaO2 95% on 6L HM\n\nGCS 9","parts":[{"id":"a","label":"Part A","prompt":"Apart from eclampsia, list the causes of seizure you would consider in this patient (4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 risk factors for pre-eclampsia/eclampsia (3 marks)"},{"id":"c","label":"Part C","prompt":"What examination features would increase your level of suspicion that this is eclampsia (3 marks)"},{"id":"d","label":"Part D","prompt":"Outline your initial management in each category below. Include drugs/dose/route that you would administer (6 marks) Category Management General management & resuscitation Pharmacotherapy of eclampsia/pre-eclampsia"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Meningoencephalitis</strong> e.g. post-epidural</div><div class=\"answer-line\">Primary epilepsy</div><div class=\"answer-line\">Hypoxia e.g. due to pulmonary embolus</div><div class=\"answer-line\">TTP</div><div class=\"answer-line\">Plus at least one not directly related to pregnancy / delivery: e.g., hypoglycaemia, toxic ingestion,</div><div class=\"answer-line\">structural intracranial e.g. bleed, ICH/SAH</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Nulliparity</div><div class=\"answer-line\">Family history of preeclampsia, previous preeclampsia and eclampsia</div><div class=\"answer-line\">Poor outcome of previous pregnancy, including intrauterine growth retardation, abruptio placentae,</div><div class=\"answer-line\">or fetal death</div><div class=\"answer-line\">Multifetal gestations, hydatid mole, fetal hydrops, primigravida</div><div class=\"answer-line\">Teen pregnancy</div><div class=\"answer-line\">Primigravida</div><div class=\"answer-line\">Patient older than 35 years</div><div class=\"answer-line\">Lower socioeconomic status</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">What examination features would increase your level of suspicion that this is eclampsia (3</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">Hypertension</div><div class=\"answer-line\">Peripheral oedema</div><div class=\"answer-line\">Hyper-reflexia → Clonus</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Outline your initial management in each category below. Include drugs/dose/route that you</div><div class=\"answer-line\">would administer (6 marks)</div><div class=\"answer-line\">Category</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"(18 marks) A 62 year old man is brought to ED via ambulance after a large spontaneous epistaxis for the last 4 hours. The ambulance officers reported he vomited at least 600mls of blood at the scene. They also report a number of empty bottles of vodka scattered around the house. They have been maintaining pressure to his anterior nose.\n\nVital signs\nP 105 bpm\n\nBP 115/54 mmHg\n\nRR 22 bpm\n\nSaO2 99% on RA","parts":[{"id":"a","label":"Part A","prompt":"List 5 key features in respect to his history (5 marks)"},{"id":"b","label":"Part B","prompt":"List 5 specific examination findings you would look for (other than haemodynamics) (5 marks)"},{"id":"c","label":"Part C","prompt":"There is evidence of significant active naso-pharyngeal bleeding from both nostrils which seems posterior despite 30 minutes firm anterior pressure. Describe a step wise approach to control his bleeding in the ED with a brief description of each (minimum 4 different methods) (8 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Epistaxis hx – duration, unilateral /bilateral, anterior/posterior, previous bleeds</div><div class=\"answer-line\">Vomited blood - ?true haematemesis or vomited blood from ingested epistaxis, any other features</div><div class=\"answer-line\">to suggest upper GIT bleed – melaena, abdo pain etc ,</div><div class=\"answer-line\">?alcoholic liver disease/Etoh intake, previous upper GIT bleed, hx of varices</div><div class=\"answer-line\">Symptoms of anaemia/blood loss – syncope/pre-syncope, chest pain, SOB</div><div class=\"answer-line\">Drug hx  - hx of blood thinners/antiplatelets/anticoag</div><div class=\"answer-line\">Any hx of nasal trauma</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">(Use head lamp, suction, nasal speculum, PPE)</div><div class=\"answer-line\">Active bleeding</div><div class=\"answer-line\">Unilateral/bilateral, anterior or posterior - look in mouth /nasopharynx</div><div class=\"answer-line\">Any areas of recent bleeding amenable to cauterisation/silver nitrate</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div><div class=\"answer-line\">Any evidence of nasal trauma or anatomical abnormality/nasal polyps/masses</div><div class=\"answer-line\">Evidence of aspiration</div><div class=\"answer-line\">Stigmata of chronic liver disease/portal HTN/ascites etc</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">There is evidence of significant active naso-pharyngeal bleeding from both nostrils which seems</div><div class=\"answer-line\">posterior despite 30 minutes firm anterior pressure. Describe a step wise approach to control his</div><div class=\"answer-line\">bleeding in the ED with a brief description of each (minimum 4 different methods) (8 marks)</div><div class=\"answer-line\">Local anaesthetic/vasoconstrictor spray (co-phenycaine or equivalent) 2-3 sprays to both nostrils</div><div class=\"answer-line\">Nasal Sponge/Tampon (expanding nasal tampon) eg Merocel. Polyvinyl alcohol. Lubricate. Original</div><div class=\"answer-line\">size may allow for easy passage along a relatively straight septum, but once it becomes wet, the</div><div class=\"answer-line\">expansion that occurs may make it difficult to reposition. Once applied, tape the safety line to the</div><div class=\"answer-line\">cheek to prevent posterior migration and allow for assistance with removal. Start on one side – if no</div><div class=\"answer-line\">control, place bilaterally. Antibiotics post.</div><div class=\"answer-line\">Rapid Rhino (longer 7.5 cm Anterior/posterior ideal) - prior to application get patient to blow nose to</div><div class=\"answer-line\">remove old clot, device must be soaked with sterile water (not saline) to activate hydrocolloid</div><div class=\"answer-line\">coating on inflatable balloon. Insert along floor of nose to hilt, inflate air, balloon may be taped to</div><div class=\"answer-line\">cheek. Start on one side – if no control, place bilaterally. Antibiotics post (Augmentin or 2nd</div><div class=\"answer-line\">generation cephalosporin)</div><div class=\"answer-line\">Double Nasal Balloon (with anterior and posterior balloon). Lubrication antibiotic ointment or water-</div><div class=\"answer-line\">based lubricant jelly. Insertion, such that the distal balloon enters the nasopharynx . Inflation of the</div><div class=\"answer-line\">distal balloon (typically with 7 to 8 mL of water), pulling it forward to lodge in the posterior</div><div class=\"answer-line\">choana. Filling the anterior balloon with about 15 mL of water until it occludes the nostril.</div><div class=\"answer-line\">Anterior Nasal packing – multiple horizontally inserted layers of ½ inch ribbon gauze covered in</div><div class=\"answer-line\">antibiotic ointment. Consider soaking in TXA.</div><div class=\"answer-line\">Foley Catheter Size 12 F catheter is lubricated with antibiotic ointment, or lubricant jelly. Passed to</div><div class=\"answer-line\">the nasopharynx, where the balloon is inflated with 7 to 8 mL of water. Clamp off end of catheter.</div><div class=\"answer-line\">Maintain anterior traction positions and lodges the balloon in the posterior nasal choana. Use with</div><div class=\"answer-line\">anterior packing/bilateral rapid rhinos.</div><div class=\"answer-line\">(NB no marks for Silver nitrate as significant active bleeding)</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"(15 marks) An 11 year old boy presents via ambulance. A basketball stand has collapsed and struck him on the left side of the face, head and neck trapping him for several minutes. He was unconscious during this time. He is sitting on the ambulance trolley. He has limited mouth opening and 2 large left through and through cheek lacerations requiring continuous oral suctioning for bleeding. There is left sided neck swelling and linear bruising overlying his left anterior neck. He is not moving his neck due to pain.\n\nVital signs\n\nGCS 15 and moving all 4 limbs to command\nP 78 bpm\n\nBP 110/65 mmHg\n\nRR 16 bpm\n\nSaO2 99% on RA","parts":[{"id":"a","label":"Part A","prompt":"Outline important aspects of the child’s initial management (10 marks)"},{"id":"b","label":"Part B","prompt":"A CT angiogram is performed. List 5 pertinent findings. (5 marks) CT IMAGES ARE SHOWN IN THE PROPS BOOKLET, PAGES 7-9"}],"propPages":["asset:img14009e8cabdb00c126","asset:img582bd23ac358beef3c","asset:img97a2345488b701cfc9","asset:img8da06b470bbc20486a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Trauma call</div><div class=\"answer-line\">Resus area with full cardiopulmonary monitoring</div><div class=\"answer-line\">Trauma assessment approach</div><div class=\"answer-line\">Primary survey with particular emphasis</div><div class=\"answer-line\">-airway/breathing (potential obstruction)</div><div class=\"answer-line\">- disability/cognition (head injury/vascular injury)</div><div class=\"answer-line\">Consideration of C-spine immobilisation (NOT collar – wouldn’t see neck, risk of obstruction etc)</div><div class=\"answer-line\">Early analgesia and antiemetic – appropriate</div><div class=\"answer-line\">Immunisation status/abx</div><div class=\"answer-line\">SW for parents</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Comminuted, displaced mandibular fracture</div><div class=\"answer-line\">Associated oedema</div><div class=\"answer-line\">Locules of free gas (subcut. emphysema) in masseter space</div><div class=\"answer-line\">Soft tissue oedema (haematoma) adjacent to common carotid</div><div class=\"answer-line\">Hypodensity/irregularity of common carotid/vascular injury (traumatic dissection)</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"(14 marks)\nA 57 year old male presents with chest pain.","parts":[{"id":"a","label":"Part A","prompt":"Complete the following table providing details of the “HEART Score” (5 marks)"},{"id":"b","label":"Part B","prompt":"For each risk “band” obtained by calculating a HEART Score, list the predicted risk of a major adverse cardiac event (MACE) (3 marks) HEART Score Risk of MACE 0-3 Low risk 4-6 Intermediate risk 7-10 High risk"},{"id":"c","label":"Part C","prompt":"This patient is “low risk” on his HEART score but insistent on further testing. You are aware that exercise stress testing in low risk patients is controversial. Explain why this is so from a biostatistics viewpoint (2 marks)"},{"id":"d","label":"Part D","prompt":"Provide a definition for shared decision making (2 marks) and outline barriers to the use of shared decision making in the ED (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(14 marks)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>For each risk “band” obtained by calculating a HEART Score, list the predicted risk of a major</td><td>adverse cardiac event (MACE) (3 marks)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">This patient is “low risk” on his HEART score but insistent on further testing. You are aware that</div><div class=\"answer-line\">exercise stress testing in low risk patients is controversial. Explain why this is so from a</div><div class=\"answer-line\">biostatistics viewpoint (2 marks)</div><div class=\"answer-line\">Low risk group have a very low prevalence of disease.  Positive predictive value of the test (EST)</div><div class=\"answer-line\">adversely affected by this low prevalence. Produces too high a proportion of false positives</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Shared decision making is a collaborative process in which patients and providers make health care</div><div class=\"answer-line\">decisions together, taking into account the best available scientific evidence as well as the patient’s</div><div class=\"answer-line\">values and preferences.</div><div class=\"answer-line\">Time constraints</div><div class=\"answer-line\">Cognitive load on clinician</div><div class=\"answer-line\">Complex information needing to be conveyed/understood &amp; discussed in time-poor, busy</div><div class=\"answer-line\">environment</div><div class=\"answer-line\">Patient health literacy</div><div class=\"answer-line\">Patient decision-making capacity</div><div class=\"answer-line\">Physician ability to rapidly and succinctly recall and communicate the benefits and trade‐offs of the</div><div class=\"answer-line\">decision</div><div class=\"answer-line\">“Many patients prefer that the physician decides”</div><div class=\"answer-line\">“When offered a choice, many patients opt for more aggressive care than they need”</div><div class=\"answer-line\">“It is too complicated for patients to know how to choose.”</div><div class=\"answer-line\">Perceived medico-legal risk</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"You have agreed to be the expedition doctor for a trek to the Everest base camp. (Altitude 5300m)","parts":[{"id":"a","label":"Part A","prompt":"Outline the proposed pathophysiology of: Acute Mountain Sickness (AMS)/High Altitude Cerebral Oedema (2 marks) High Altitude Pulmonary Oedema (2 marks)"},{"id":"b","label":"Part B","prompt":"List 2 risk factors for the development of High Altitude Pulmonary Oedema at any given altitude (2 marks)"},{"id":"c","label":"Part C","prompt":"List 5 clinical features of AMS (5 marks)"},{"id":"d","label":"Part D","prompt":"For severe High Altitude Pulmonary Oedema, list 4 treatment options (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Outline the proposed pathophysiology of:</div><div class=\"answer-line\">Acute Mountain Sickness (AMS)/High Altitude Cerebral Oedema (2 marks)</div><div class=\"answer-line\">Vasogenic cerebral oedema. Hypoxia appears to cause cerebral vasodilatation, leading to increased</div><div class=\"answer-line\">cerebral blood volume and blood flow.</div><div class=\"answer-line\">Leaky BBB – due to loss of autoregulation and increased permeability.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">List 2 risk factors for the development of High Altitude Pulmonary Oedema at any given altitude</div><div class=\"answer-line\">(2 marks)</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div><div class=\"answer-line\">Rapid ascent</div><div class=\"answer-line\">Genetic predisposition</div><div class=\"answer-line\">Any pre-existing pulmonary hypertension (e.g. previous VTE/PE, cardiac shunts – e.g. ASD)</div><div class=\"answer-line\">Exertion</div><div class=\"answer-line\">Cold</div><div class=\"answer-line\">Use of sleeping medication</div><div class=\"answer-line\">Excessive salt ingestion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Headache – worse with bending over or valsalva</div><div class=\"answer-line\">Anorexia, nausea, sometimes vomiting</div><div class=\"answer-line\">Lassitude, weakness, irritability</div><div class=\"answer-line\">Retinal haemorrhages</div><div class=\"answer-line\">Fluid retention - peripheral/facial oedema</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Immediate descent</div><div class=\"answer-line\">Oxygen</div><div class=\"answer-line\">Minimise exertion</div><div class=\"answer-line\">Nifedipine</div><div class=\"answer-line\">Portable hyperbaric compression chamber</div><div class=\"answer-line\">CPAP/EPAP mask</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 2 year old boy has ingested iron tablets. He presents with his mother and he currently seems well. You calculate that he has possibly ingested 90mg/kg elemental iron.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table (4 marks) Elemental iron dose System involved/Effects <20mg/kg 20-60mg/kg >60-120mg/kg >120mg/kg"},{"id":"b","label":"Part B","prompt":"Complete the table of classical stages of iron toxicity (5 marks) Time post ingestion Clinical features 0-6 hours 6-12 hours 12-48 hours 2-5 days 2-6 weeks"},{"id":"c","label":"Part C","prompt":"You obtain an Xray. List 2 relevant findings (2 marks)\nAN XRAY IS SHOWN IN THE PROPS BOOKLET, PAGE 10"},{"id":"d","label":"Part D","prompt":"How does this xray alter your management plan (2 marks)"},{"id":"e","label":"Part E","prompt":"List 3 blood tests that you will order and your reasoning for doing so (3 marks)"}],"propPages":["asset:img24a538af84538c0188"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">A 2 year old boy has ingested iron tablets. He presents with his mother and he currently seems well.</div><div class=\"answer-line\">You calculate that he has possibly ingested 90mg/kg elemental iron.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Elemental iron dose</div><div class=\"answer-line\">System involved/Effects</div><div class=\"answer-line\">&lt;20mg/kg</div><div class=\"answer-line\">Asymptomatic</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Right upper zone dense consolidation</div><div class=\"answer-line\">No evidence of gastric iron tablets</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">PO iron unlikely - No need to plan decontamination via endoscopy or WBI</div><div class=\"answer-line\">Other complications - May need bronchoscopy to remove inhaled Fe tablets</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Serum Fe level at 4-6 hours – confirm absorption</div><div class=\"answer-line\">Lactate</div><div class=\"answer-line\">Acid base calculation on VBG</div><div class=\"answer-line\">EUC to calculate AG</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 32 year old with diabetes and bipolar disorder presents with disruptive behavior. She appears disorientated, ataxic and complains of nausea and vomiting for the last two weeks.\n\nVital signs\n\nTemp 37.4 deg C\n\nHR 110 bpm\n\nBP 90/60 mmHg\n\nRR 22 bpm\n\nSaO2 97% on RA\nHer lithium level is 3 mmol/L.","parts":[{"id":"a","label":"Part A","prompt":"List four potential precipitating factors you would consider in this patient that may have resulted in lithium toxicity (4 marks)"},{"id":"b","label":"Part B","prompt":"Urine testing bHCG confirms pregnancy and a probable UTI. List four antibiotics used to treat UTI and discuss why you would or would not use them in pregnancy (4 marks)"},{"id":"c","label":"Part C","prompt":"Name 3 classes of drugs (with 2 examples each) seen in overdose that are not bound by charcoal (3 marks)"},{"id":"d","label":"Part D","prompt":"Name 3 toxicokinetic features of a drug that make it amenable or appropriate to enhanced\nelimination by haemodialysis (3 marks)"},{"id":"e","label":"Part E","prompt":"List 4 drugs whose elimination is enhanced by haemodialysis (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">List four potential precipitating factors you would consider in this patient that may have resulted</div><div class=\"answer-line\">in lithium toxicity (4 marks)</div><div class=\"answer-line\">Pre-renal impairment</div><div class=\"answer-line\">dehydration</div><div class=\"answer-line\">pregnancy with hyperemesis</div><div class=\"answer-line\">UTI</div><div class=\"answer-line\">lithium induced nephrogenic diabetes insipidus</div><div class=\"answer-line\">DKA/HHS</div><div class=\"answer-line\">Drug interaction with impaired renal excretion - NSAIDs</div><div class=\"answer-line\">Hyponatraemia</div><div class=\"answer-line\">Acute overdose in the setting of chronic ingestion</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Urine testing bHCG confirms pregnancy and a probable UTI.  List four antibiotics used to treat</div><div class=\"answer-line\">UTI and discuss why you would or would not use them in pregnancy (4 marks)</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div><div class=\"answer-line\">Safe</div><div class=\"answer-line\">nitrofurantoin (avoid after 36/40)</div><div class=\"answer-line\">amoxycillin (may be resistent, depends on local sens but safe in preg)</div><div class=\"answer-line\">trimethoprim (after the first trimester, folic acid antagonist may increase neural tube</div><div class=\"answer-line\">defects in first trimester)</div><div class=\"answer-line\">cephalexin (broad spectrum but safe in pregnancy)</div><div class=\"answer-line\">Less optimal</div><div class=\"answer-line\">tetracyclines - tooth discolouration</div><div class=\"answer-line\">norfloxacin - renal abnormalities</div><div class=\"answer-line\">ciprofloxacin - avoid in pregnancy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Name 3 classes of drugs (with 2 examples each) seen in overdose that are not bound by charcoal</div><div class=\"answer-line\">(3 marks)</div><div class=\"answer-line\">Toxic alcohols - methanol, ethylene glycol, isopropyl glycol, ethanol</div><div class=\"answer-line\">Heavy metals - iron, lead, potassium, mercury, arsenic, cyanide</div><div class=\"answer-line\">Acids/alkali</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Name 3 toxicokinetic features of a drug that make it amenable or appropriate to enhanced</div><div class=\"answer-line\">elimination by haemodialysis (3 marks)</div><div class=\"answer-line\">Small Vd</div><div class=\"answer-line\">-low protein binding</div><div class=\"answer-line\">-small molecular weight</div><div class=\"answer-line\">-life threatening</div><div class=\"answer-line\">-no effective antidote</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Carbemazepine, Toxic alcohols, Sodium valproate, Theophylline, Phenobarbitone, Salicyclate,</div><div class=\"answer-line\">Potassium</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 25 year old male presents with a large area of cellulitis of his left anterior thigh.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table identifying specific bacteria of concern for each specific situation (4 marks) Situation Specific organism(s) Human bite Cat bite Fresh water wound Salt water wound"},{"id":"b","label":"Part B","prompt":"List 6 clinical features that help to distinguish necrotising fasciitis from uncomplicated cellulitis (6 marks)"},{"id":"c","label":"Part C","prompt":"List the common organisms responsible for necrotising fasciitis (4 marks) and state the recommended empiric antibiotic choice for undifferentiated necrotising fasciitis (doses not required) (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>A 25 year old male presents with a large area of cellulitis of his left anterior thigh.</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">List 6 clinical features that help to distinguish necrotising fasciitis from uncomplicated cellulitis (6</td></tr><tr><td colspan=\"2\">marks)</td></tr><tr><td colspan=\"2\">History sepsis (fever, chills, myalgias)</td></tr><tr><td colspan=\"2\">severe constant pain that is out of proportion to clinical findings</td></tr><tr><td colspan=\"2\">evidence of developing organ failures</td></tr><tr><td colspan=\"2\">underlying risk factors (DM, ETOH abuse, PVD, renal failure, malignancy, local penetrating</td></tr><tr><td colspan=\"2\">trauma or animal bite, recent surgery (e.g. abdominal or peritoneal surgery)</td></tr><tr><td colspan=\"2\">commonly an extremity -&gt; but can affect anywhere (e.g. perineum = Fournier’s gangrene)</td></tr><tr><td colspan=\"2\">Examination</td></tr><tr><td>Local</td><td>erythematous, tender, swollen</td></tr><tr><td colspan=\"2\">skin becomes smooth, shiny and tensely swollen - darkens, patchy, blisters, bullae-gangrene</td></tr><tr><td colspan=\"2\">wooden-hard feel of the subcutaneous tissue</td></tr><tr><td colspan=\"2\">oedema beyond the margin of erythema</td></tr><tr><td colspan=\"2\">crepitus (gas gangrene)</td></tr><tr><td colspan=\"2\">Systemic</td></tr><tr><td colspan=\"2\">fever, tachycardia</td></tr><tr><td colspan=\"2\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</td></tr><tr><td colspan=\"2\">haemodynamic instability</td></tr><tr><td colspan=\"2\">rapid spread on re-examination</td></tr><tr><td colspan=\"2\">And from TG:</td></tr><tr><td colspan=\"2\">Clinical features that suggest a necrotising infection of the skin and deeper tissues include:</td></tr><tr><td>•</td><td>constant severe pain, even if skin inflammation is initially limited</td></tr><tr><td>•</td><td>bullae</td></tr><tr><td>•</td><td>skin necrosis or bruising</td></tr><tr><td>•</td><td>the subcutaneous tissue is hard (&#x27;wooden&#x27;) and painful to touch</td></tr><tr><td>•</td><td>oedema beyond the margin of erythema</td></tr><tr><td>•</td><td>cutaneous anaesthesia</td></tr><tr><td>•</td><td>gas in the soft tissues (detected by palpation or imaging)</td></tr><tr><td>•</td><td>systemic toxicity, including fever, leucocytosis, high C-reactive protein (CRP), delirium or renal</td></tr><tr><td colspan=\"2\">failure</td></tr><tr><td>•</td><td>rapidly spreading infection.</td></tr><tr><td colspan=\"2\">Penetrating and crush injuries are particularly likely to lead to necrotising skin infection, but such</td></tr><tr><td colspan=\"2\">infections also occur following some surgical procedures. Life-threatening <em>S. pyogenes</em> necrotising</td></tr><tr><td colspan=\"2\">fasciitis can occur spontaneously or following varicella infection (chickenpox) in children and adults.</td></tr><tr><td colspan=\"2\">Diabetes mellitus is also a risk factor for necrotising skin infection.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">History sepsis (fever, chills, myalgias)</td></tr><tr><td colspan=\"2\">severe constant pain that is out of proportion to clinical findings</td></tr><tr><td colspan=\"2\">evidence of developing organ failures</td></tr><tr><td colspan=\"2\">underlying risk factors (DM, ETOH abuse, PVD, renal failure, malignancy, local penetrating</td></tr><tr><td colspan=\"2\">trauma or animal bite, recent surgery (e.g. abdominal or peritoneal surgery)</td></tr><tr><td colspan=\"2\">commonly an extremity -&gt; but can affect anywhere (e.g. perineum = Fournier’s gangrene)</td></tr><tr><td colspan=\"2\">Examination</td></tr><tr><td>Local</td><td>erythematous, tender, swollen</td></tr><tr><td colspan=\"2\">skin becomes smooth, shiny and tensely swollen - darkens, patchy, blisters, bullae-gangrene</td></tr><tr><td colspan=\"2\">wooden-hard feel of the subcutaneous tissue</td></tr><tr><td colspan=\"2\">oedema beyond the margin of erythema</td></tr><tr><td colspan=\"2\">crepitus (gas gangrene)</td></tr><tr><td colspan=\"2\">Systemic</td></tr><tr><td colspan=\"2\">fever, tachycardia</td></tr><tr><td colspan=\"2\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</td></tr><tr><td colspan=\"2\">haemodynamic instability</td></tr><tr><td colspan=\"2\">rapid spread on re-examination</td></tr><tr><td colspan=\"2\">And from TG:</td></tr><tr><td colspan=\"2\">Clinical features that suggest a necrotising infection of the skin and deeper tissues include:</td></tr><tr><td>•</td><td>constant severe pain, even if skin inflammation is initially limited</td></tr><tr><td>•</td><td>bullae</td></tr><tr><td>•</td><td>skin necrosis or bruising</td></tr><tr><td>•</td><td>the subcutaneous tissue is hard (&#x27;wooden&#x27;) and painful to touch</td></tr><tr><td>•</td><td>oedema beyond the margin of erythema</td></tr><tr><td>•</td><td>cutaneous anaesthesia</td></tr><tr><td>•</td><td>gas in the soft tissues (detected by palpation or imaging)</td></tr><tr><td>•</td><td>systemic toxicity, including fever, leucocytosis, high C-reactive protein (CRP), delirium or renal</td></tr><tr><td colspan=\"2\">failure</td></tr><tr><td>•</td><td>rapidly spreading infection.</td></tr><tr><td colspan=\"2\">Penetrating and crush injuries are particularly likely to lead to necrotising skin infection, but such</td></tr><tr><td colspan=\"2\">infections also occur following some surgical procedures. Life-threatening <em>S. pyogenes</em> necrotising</td></tr><tr><td colspan=\"2\">fasciitis can occur spontaneously or following varicella infection (chickenpox) in children and adults.</td></tr><tr><td colspan=\"2\">Diabetes mellitus is also a risk factor for necrotising skin infection.</td></tr><tr><td colspan=\"2\">iii.</td></tr><tr><td colspan=\"2\">recommended empiric antibiotic choice for undifferentiated necrotising fasciitis (doses not</td></tr><tr><td colspan=\"2\">required)  (2 marks)</td></tr><tr><td colspan=\"2\">Streptococci esp Group A B-haemolytic, S pyogenes</td></tr><tr><td colspan=\"2\">Staph aureus</td></tr><tr><td colspan=\"2\">Clostridium species esp  C perfringens</td></tr><tr><td colspan=\"2\">Mixed aerobe-anaerobic flora – E coli, B fragilis</td></tr><tr><td colspan=\"2\">Empiric antibiotics</td></tr><tr><td colspan=\"2\">For empirical therapy, if diagnosis is uncertain, until the results of tissue and blood cultures are</td></tr><tr><td colspan=\"2\">available, use:</td></tr><tr><td colspan=\"2\">meropenem 1 g (child: 25 mg/kg up to 1 g) IV, 8-hourly <em>necrotising skin infection, empirical therapy</em></td></tr><tr><td colspan=\"2\">PLUS</td></tr><tr><td colspan=\"2\">vancomycin IV;</td></tr><tr><td colspan=\"2\">PLUS</td></tr><tr><td colspan=\"2\">clindamycin 600 mg (child: 15 mg/kg up to 600 mg) IV, 8-hourly</td></tr><tr><td colspan=\"2\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"This question concerns pulse oximetry and waveform capnography.","parts":[{"id":"a","label":"Part A","prompt":"Describe how a pulse oximeter works (4 marks)"},{"id":"b","label":"Part B","prompt":"List three sources of error (with brief explanation) in pulse oximetry readings (6 marks)"},{"id":"c","label":"Part C","prompt":"Explain what is happening during Phase III of a normal capnogram (1 mark)"},{"id":"d","label":"Part D","prompt":"Write brief notes on three ways in which waveform capnography is useful in cardiac arrest (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Device analyses only pulsatile blood (i.e. arterial) to avoid errors due to light absorption by Hb in</div><div class=\"answer-line\">venous blood</div><div class=\"answer-line\">One side of device has two light emitting diodes using two different wavelengths  – 660nm &amp;</div><div class=\"answer-line\">940nm.</div><div class=\"answer-line\">Light waves pass thru finger (or wherever) &amp; are detected by sensor on opposite side. The intensity</div><div class=\"answer-line\">of light received reflects absorption by de-oxyHb (660) and HbO2 (940).</div><div class=\"answer-line\">The device converts “light density” to “chemical density” (= concentration) and ratio of HbO2 to</div><div class=\"answer-line\">total Hb is expressed as %</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Dyshaemoglobinaemias</div><div class=\"answer-line\">CoHb, metHb – affected red cells have decreased O2 carrying capacity. These abnormal Hb</div><div class=\"answer-line\">species absorb light at both wavelengths – and a spurious % is reported. Arterial blood gas</div><div class=\"answer-line\">measurements are not so affected</div><div class=\"answer-line\">Peripheral vasoconstriction – can cause inaccurate measure e.g. with sensor at fingertips</div><div class=\"answer-line\">Tricuspid regurg, high airway pressures &amp; Valsalva can all produce venous pulsations which could be</div><div class=\"answer-line\">read by the device</div><div class=\"answer-line\">Nail polish – dark nail polish produces a small discrepancy b/w SpO2 and SaO2</div><div class=\"answer-line\">Motion artefact – esp shivering &amp; in transport</div><div class=\"answer-line\">Ambient light – fluorescent, xenon, infrared can all produce falsely elevated readings</div><div class=\"answer-line\">Hypotension – remains accurate until very low blood pressures</div><div class=\"answer-line\">Anaemia – oximetry accurate to very low Hb levels</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">4 phases</div><div class=\"answer-line\">Phase I (inspiratory baseline) reflects inspired gas, which is normally devoid of carbon dioxide</div><div class=\"answer-line\">Phase II (expiratory upstroke) is the transition between VDana, which does not participate in gas</div><div class=\"answer-line\">exchange, and alveolar gas from the respiratory bronchioles and alveoli</div><div class=\"answer-line\">Phase III is the alveolar plateau. Traditionally, PCO2 of the last alveolar gas sampled at the airway</div><div class=\"answer-line\">opening is called the PETCO2</div><div class=\"answer-line\">Phase 0 is the inspiratory downstroke, the beginning of the next inspiration</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Write brief notes on three ways in which waveform capnography is useful in cardiac arrest (3</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">The most definitive evidence of correct endotracheal tube placement</div><div class=\"answer-line\">During CPR, if endotracheal tube correctly placed should see abnormal (typically low) ETCO2</div><div class=\"answer-line\">trace but not a flat one</div><div class=\"answer-line\">Height of CO2 waveform is a measure of adequacy of cardiac output generated during CPR</div><div class=\"answer-line\">Aim should be ETCO2 &gt; 20mmHg. If inadequate seek reason – e.g. poor quality CPR/operator</div><div class=\"answer-line\">fatigue, pneumothorax, tamponade…</div><div class=\"answer-line\">Marked, abrupt increase in ETCO2 suggests ROSC.</div><div class=\"answer-line\">ETCO2 may help predict survival and/or guide decisions about cessation</div><div class=\"answer-line\">In patients undergoing CPR, ETCO2 &gt; 10mmHg are more likely to have ROSC</div><div class=\"answer-line\">&gt;20 mmHg at 20 minutes of CPR → higher chance of ROSC</div><div class=\"answer-line\">&lt;10 mmHg at 20 minutes of CPR → almost no chance of ROSC</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"Your resident has just seen a 30 year old man with chest pain suspicious for pericarditis.","parts":[{"id":"a","label":"Part A","prompt":"List 3 criteria which should be met to make a diagnosis of pericarditis (3 marks)"},{"id":"b","label":"Part B","prompt":"The resident could not hear a pericardial rub. Detail how to auscultate for a pericardial rub and describe what sound might be expected (3 marks)"},{"id":"c","label":"Part C","prompt":"List 4 ECG features that help to distinguish Benign Early Repolarisation (BER) from pericarditis (4 marks)"},{"id":"d","label":"Part D","prompt":"Pericarditis is the working diagnosis for this patient and a decision is made to commence an NSAID and colchicine. Outline the progression of clinical features in colchicine overdose (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Diagnosis requires at least two of the following criteria: characteristic sharp, pleuritic chest pain;</div><div class=\"answer-line\">pericardial friction rub; suggestive changes on electrocardiography; and a new or worsening</div><div class=\"answer-line\">pericardial effusion.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">The resident could not hear a pericardial rub. Detail how to auscultate for a pericardial rub and</div><div class=\"answer-line\">describe what sound might be expected (3 marks)</div><div class=\"answer-line\">Auscultation exposes a pericardial friction rub (pathognomonic sign for pericarditis), due to</div><div class=\"answer-line\">increased friction of inflamed pericardial layers, in about one third of patients with acute</div><div class=\"answer-line\">pericarditis. It is a superficial scratchy or squeaking sound, best heard with the diaphragm of the</div><div class=\"answer-line\">stethoscope over the left sternal border with the patient leaning forward. It typically consists of</div><div class=\"answer-line\">three phases, corresponding to movement of the heart during atrial systole (absent in atrial</div><div class=\"answer-line\">fibrillation), ventricular systole and the rapid filling phase of early ventricular diastole. Sometimes,</div><div class=\"answer-line\">pericardial rub has only two components or even one component. Notably, pericardial friction rub</div><div class=\"answer-line\">can disappear not only at healing of pericarditis, but also when there is development of more</div><div class=\"answer-line\">pericardial fluid in the pericardial sac, reflecting either improvement or exacerbation of the disease.</div><div class=\"answer-line\">In addition, friction rub in acute pericarditis can vary in intensity from moment to moment, which</div><div class=\"answer-line\">rarely happens with the other forms of pericarditis. The auscultation of pericardial friction rub is</div><div class=\"answer-line\">highly specific for acute pericarditis (specificity approximately 100%).</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">List 4 ECG features that help to distinguish Benign Early Repolarisation (BER) from pericarditis (4</td></tr><tr><td colspan=\"2\">marks)</td></tr><tr><td colspan=\"2\">Features suggesting BER</td></tr><tr><td>•</td><td>ST elevation limited to the precordial leads</td></tr><tr><td>•</td><td>Absence of PR depression</td></tr><tr><td>•</td><td>Prominent T waves</td></tr><tr><td>•</td><td>ST segment / T wave ratio &lt; 0.25</td></tr><tr><td>•</td><td>Characteristic “fish-hook” appearance in V4</td></tr><tr><td>•</td><td>ECG changes usually stable over time (i.e non-progressive)</td></tr><tr><td colspan=\"2\">Features suggesting pericarditis</td></tr><tr><td>•</td><td>Generalised ST elevation</td></tr><tr><td>•</td><td>Presence of PR depression</td></tr><tr><td>•</td><td>Normal T wave amplitude</td></tr><tr><td>•</td><td>ST segment / T wave ratio &gt; 0.25</td></tr><tr><td>•</td><td>Absence of “fish hook” appearance in V4</td></tr><tr><td colspan=\"2\">ECG changes evolve slowly over time</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Pericarditis is the working diagnosis for this patient and a decision is made to commence an</div><div class=\"answer-line\">NSAID and colchicine. Outline the progression of clinical features in colchicine overdose (3</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">2-24 hours – latent/asymptomatic period followed by development of GIT symptoms – nausea,</div><div class=\"answer-line\">vomiting, diarrhoea, haemorrhagic gastroenteritis. Severe GI fluid/electrolyte losses.</div><div class=\"answer-line\">24-72 hours - Effects include CNS toxicity, bone marrow depression, hepatocellular damage, muscle</div><div class=\"answer-line\">damage, respiratory distress, myocardial injury and renal damage. Multiple organ failure caused by</div><div class=\"answer-line\">tissue damage including bone marrow hypoplasia is likely to be followed by agranulocytosis,</div><div class=\"answer-line\">leucopenia, thrombocytopenia and disseminated intravascular coagulation. Death may occur as a</div><div class=\"answer-line\">result of respiratory depression, cardiovascular collapse or sepsis</div><div class=\"answer-line\">&gt; 7 days – in survivors: alopecia, leukocytosis</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A patient presents to your ED with marked SOB and hypoxia.","parts":[{"id":"a","label":"Part A","prompt":"List 4 relevant findings on the chest Xray (4 marks)\nA CHEST X-RAY IS SHOWN IN THE PROPS BOOKLET, PAGE 11"},{"id":"b","label":"Part B","prompt":"List 4 potential underlying pathologies (4 marks)\nA pleural aspirate is performed. Fluid Protein 48 g/L\nSerum protein 62 g/L (60-78)\nFluid LDH 120 U/L Serum LDH 148 U/L (60-160)\n\nGlucose\n1.9 mmol/L"},{"id":"c","label":"Part C","prompt":"What type of effusion is this and why (1 mark) and what are the 2 most likely differential diagnoses (3 marks)"},{"id":"d","label":"Part D","prompt":"List 4 further relevant investigations (4 marks)"}],"propPages":["asset:imgb3b79e9a290bee589a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Significant bilateral opacities in lower zones</div><div class=\"answer-line\">Bilateral significant pleural effusions</div><div class=\"answer-line\">Important negatives -No signs of trauma, APO,  grossly clear apex</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Malignancy – Lung, Breast, Ovarian,</div><div class=\"answer-line\">Infective -  Pneumonia, Empyema, TB</div><div class=\"answer-line\">Cardiac – CCF, Post Op, Pericarditis</div><div class=\"answer-line\">Pulmonary Emboli</div><div class=\"answer-line\">Autoimmune – RA, SLE, Sarcoidosis</div><div class=\"answer-line\">Other – Thyroid, Liver failure, Renal- Nephrotic/nephritic, Trauma</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Exudate effusion – Fluids:serum     prot &gt;0.5       LDH &gt;0.6</div><div class=\"answer-line\">Malignancy</div><div class=\"answer-line\">Infection – Pneumonia/Empyema</div><div class=\"answer-line\">Bloody exudate with low glucose – malignancy/infection most likely</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Further lab assessment of the fluid – Lactate, pH, Hct, Triglycerides, Amylase</div><div class=\"answer-line\">Cytology</div><div class=\"answer-line\">MC+S and gram stain</div><div class=\"answer-line\">Imaging – Bedside US/HRCT chest</div><div class=\"answer-line\">Bronchoscopy</div><div class=\"answer-line\">Biopsy</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 55 year old male presents from homeless shelter with symptoms of fever. Over the preceding 6 months he had been living in a crowded and squalid disused house. The shelter staff are aware that there has been a recent diagnosis of tuberculosis at the site.","parts":[{"id":"a","label":"Part A","prompt":"Apart from the homeless, list 4 other higher risk population groups in Australia for tuberculosis (4 marks)"},{"id":"b","label":"Part B","prompt":"List 4 radiographic findings of patients with acute primary pulmonary TB (4 marks)"},{"id":"c","label":"Part C","prompt":"The NUM of the ED has infection control concerns. List the specific transmission precaution for\nTB and 3 features of this strategy (4 marks)"},{"id":"d","label":"Part D","prompt":"Initial sputum staining has confirmed the presence of Acid Fast Bacilli. An Infectious Diseases Specialist has suggested commencing Standard Short Course Therapy. List the 4 antibiotics of this therapy (2 marks)"},{"id":"e","label":"Part E","prompt":"Concerns are raised for this patient’s likely compliance to this antibiotic regimen. In addition to compliance what are the potential benefits of Direct Observed Therapy (DOT) (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Apart from the homeless, list 4 other higher risk population groups in Australia for tuberculosis</div><div class=\"answer-line\">(4 marks)</div><div class=\"answer-line\">Immunosuppressed (include HIV)</div><div class=\"answer-line\">Institutional living</div><div class=\"answer-line\">Immigrants/Travellers from TB high incidence countries (eg India, China)</div><div class=\"answer-line\">Contact with a case of known active TB</div><div class=\"answer-line\">Indigenous Australians (in localised areas)</div><div class=\"answer-line\">Healthcare workers</div><div class=\"answer-line\">Elderly</div><div class=\"answer-line\">Small risk with (DM, Alcoholism) but do not get mark (question asks for “high risk groups”)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Normal CXR (V common)</div><div class=\"answer-line\">Hilar adenopathy</div><div class=\"answer-line\">Pleural effusions</div><div class=\"answer-line\">Perihilar/right-sided/basal segment upper lobe infiltrates</div><div class=\"answer-line\">Not accepted are changes of healed primary TB/reactivation TB/Primary progressive:</div><div class=\"answer-line\">Specifically state apical infiltrates/consolidation (Reactivation)</div><div class=\"answer-line\">Calcific changes (“Ghon focus”)/cavitating lesions/ Tuberculoma (Healed primary TB)</div><div class=\"answer-line\">Diffuse nodular changes (Miliary TB-haematogenous spread in primary progressive disease-rare)</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">The NUM of the ED has infection control concerns. List the specific transmission precaution for</div><div class=\"answer-line\">TB and 3 features of this strategy. (4 marks)</div><div class=\"answer-line\">Transmission precaution</div><div class=\"answer-line\">Air-borne/Aerosol precautions<strong> </strong></div><div class=\"answer-line\">Features</div><div class=\"answer-line\">Isolation</div><div class=\"answer-line\">Negative-pressure room</div><div class=\"answer-line\">High filtration Mask (N95)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Initial sputum staining has confirmed the presence of Acid Fast Bacilli. An Infectious Diseases</div><div class=\"answer-line\">Specialist has suggested commencing Standard Short Course Therapy. List the 4 antibiotics of</div><div class=\"answer-line\">this therapy (2 marks)</div><div class=\"answer-line\">Isoniazid</div><div class=\"answer-line\">Rifampicin</div><div class=\"answer-line\">Pyrazinamide</div><div class=\"answer-line\">Ethambutol</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Concerns are raised for this patient’s likely compliance to this antibiotic regimen. In addition to</div><div class=\"answer-line\">compliance what are the potential benefits of Direct Observed Therapy (DOT) (2 marks)</div><div class=\"answer-line\">Prevent further transmission of TB</div><div class=\"answer-line\">Prevent development of drug resistance</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"You are asked by the nurses to chart analgesia for a patient, seen by a colleague on the previous shift, admitted under orthopaedics and ready for the ward. You were not given a comprehensive handover and so review the notes: 42 year old man Jetski injury. Jumped into air off wave and landed with heavy impact Hyperextension injury to the left knee, patient reports knee dislocated Subsequent deformity and significant pain","parts":[{"id":"a","label":"Part A","prompt":"List 4 relevant findings on the Xray (4 marks)\nXRAYS ARE SHOWN IN THE PROPS BOOKLET, PAGES 12-13"},{"id":"b","label":"Part B","prompt":"Complete the table identifying two potential complications related to this mechanism of injury and how you could assess for each (4 marks) Complication Means of assessment"},{"id":"c","label":"Part C","prompt":"A long leg cast has been applied and the leg is elevated. The patient is still in extreme pain despite opioid analgesia. List two possible explanations for his ongoing severe pain (2 marks) He is started on fentanyl PCA and transferred to the ward. He goes to OT the next day and the ED director, receives a call from the orthopaedic consultant advising that the POP backslab applied in ED was found to be a circumferential below knee POP and the patient needed a fasciotomy for compartment syndrome. The orthopaedic team have put in an incident notification."},{"id":"d","label":"Part D","prompt":"List 4 steps involved in managing this incident (4 marks)"}],"propPages":["asset:img9587c3178e8b973e58","asset:img5d9bbf30487b44ca28"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Comminuted proximal tibial fracture with multiple fracture lines through the metaphysis.</div><div class=\"answer-line\">Fracture lines extend into the lateral tibial plateau articular surface</div><div class=\"answer-line\">Minimal displacement/depression of the medial tibial plateau</div><div class=\"answer-line\">Undisplaced fracture of the left fibular neck</div><div class=\"answer-line\">Not dislocated (enlocated)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Complete the table identifying two potential complications related to this mechanism of injury</td><td>and how you could assess for each (4 marks)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">A long leg cast has been applied and the leg is elevated. The patient is still in extreme pain</div><div class=\"answer-line\">despite opioid analgesia. List two possible explanations for his ongoing severe pain (2 marks)</div><div class=\"answer-line\">Compartment syndrome from injury</div><div class=\"answer-line\">Compartment syndrome developing from tight POP cast</div><div class=\"answer-line\">Opioid dependence and tolerance</div><div class=\"answer-line\">Missed other injury elsewhere</div><div class=\"answer-line\">Inadequate analgesia doses (for his size)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Open disclosure to patient and advise will follow up</div><div class=\"answer-line\">Assessment of event – review notes, discuss with staff involved, note details of POP application, limb</div><div class=\"answer-line\">obs</div><div class=\"answer-line\">Review processes for POP application</div><div class=\"answer-line\">Consider a formal guideline or protocol for POP application</div><div class=\"answer-line\">Discuss case at M&amp;M and educate staff</div><div class=\"answer-line\">Review other issues: inadequate medical handover, failure to recognise compartment</div><div class=\"answer-line\">syndrome/severe pain</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice 21 June 2018</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
